let cached: protobuf.Root | undefined;

/** The recovered schema root, built once on first use. */
export function recoveredRoot(): protobuf.Root {
  cached ??= protobuf.Root.fromJSON(RECOVERED_ROOT as never) as protobuf.Root;
  return cached;
}

/** A recovered message type by "namespace.Message" (e.g. "astro.ReqGotoDSO"). */
export function recoveredType(ref: string): protobuf.Type {
  const t = recoveredRoot().lookup(ref);
  if (!(t instanceof protobuf.Type)) throw new Error(`protocol: no recovered type ${ref}`);
  return t;
}

/** Whether the recovered schemas define this type. */
export function hasRecoveredType(ref: string): boolean {
  try {
    return recoveredType(ref) instanceof protobuf.Type;
  } catch {
    return false;
  }
}
